CREATE OR REPLACE FUNCTION public.validate_tag_item_company() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.company_slug IS NULL OR NOT EXISTS(SELECT 1 FROM public.items WHERE id=NEW.item_id AND company_slug=NEW.company_slug) THEN RAISE EXCEPTION 'Tag and item must belong to the same company'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_tag_item_company() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_tag_item_company BEFORE INSERT OR UPDATE ON public.tag_items FOR EACH ROW EXECUTE FUNCTION public.validate_tag_item_company();
CREATE OR REPLACE FUNCTION public.validate_rule_company() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.item_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.items WHERE id=NEW.item_id AND company_slug=NEW.company_slug) THEN RAISE EXCEPTION 'Rule item must belong to the same company'; END IF; IF EXISTS(SELECT 1 FROM unnest(NEW.recipient_user_ids) AS recipient(id) WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=recipient.id AND p.company_slug=NEW.company_slug)) THEN RAISE EXCEPTION 'Rule recipients must belong to the same company'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_rule_company() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_rule_company BEFORE INSERT OR UPDATE ON public.alert_rules FOR EACH ROW EXECUTE FUNCTION public.validate_rule_company();
ALTER POLICY "Admins manage company rules" ON public.alert_rules USING(public.can_manage_company(company_slug)) WITH CHECK(public.can_manage_company(company_slug));
ALTER POLICY "Admins can insert own company settings" ON public.company_settings WITH CHECK(public.can_manage_company(company_slug));
ALTER POLICY "Admins can update own company settings" ON public.company_settings USING(public.can_manage_company(company_slug)) WITH CHECK(public.can_manage_company(company_slug));
CREATE OR REPLACE FUNCTION public.audit_rule_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE row_data jsonb; BEGIN IF TG_OP='DELETE' THEN row_data:=to_jsonb(OLD); ELSE row_data:=to_jsonb(NEW); END IF; INSERT INTO public.audit_log(company_slug,user_id,action,details) VALUES(row_data->>'company_slug',auth.uid(),'rule.'||lower(TG_OP),jsonb_build_object('verified',true,'rule_id',row_data->>'id')); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.audit_rule_change() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER audit_rule_change AFTER INSERT OR UPDATE OR DELETE ON public.alert_rules FOR EACH ROW EXECUTE FUNCTION public.audit_rule_change();